// Why Code: prompt d'extraction, schéma de sortie et bloc PDF ou texte du document client.
const input = $json.body ?? $json;
const pdf = String(input.pdf ?? '').trim();
const texte = String(input.texte ?? '').trim();
if (!pdf && !texte) throw new Error('Ni PDF ni texte reçu : envoyer "pdf" (base64) ou "texte".');

const SYSTEM = `Tu es l'assistant d'un consultant fonctionnel Odoo. Tu lis un document client (compte rendu de rendez-vous, transcription, cahier des charges) pour préparer un paramétrage d'Odoo 20.0. Tu réponds en français.

Règles impératives :
1. "besoins" : un besoin par fonctionnalité à paramétrer dans Odoo (ex. vente avec signature en ligne, réapprovisionnement à la commande, tickets de support). Regroupe ce qui se paramètre au même endroit, sépare ce qui relève de modules différents. 12 besoins au maximum.
   - "titre" : quelques mots ;
   - "besoin" : une phrase autonome, compréhensible sans le document, qui décrit ce que le client veut obtenir dans Odoo, avec le vocabulaire métier du document ;
   - "contexte" : les données du document utiles à ce besoin (noms, délais, montants, sites, adresses), recopiées telles quelles, chacune suivie entre parenthèses de l'objet auquel le document la rattache (ex. « Lumitech SAS (fournisseur des luminaires sur mesure uniquement) ») ; chaîne vide s'il n'y en a pas ;
   - "extrait" : la phrase du document d'où vient le besoin.
2. "donnees_client" : chaque donnée factuelle présente dans le document (société, interlocuteur, fournisseurs, délais, montants, sites, volumes, adresses e-mail). "valeur" est recopiée du document, "objet" dit à quoi le document la rattache (une famille de produits, un flux, un site, la société ; « général » si elle vaut pour tout), "extrait" est la phrase d'où elle vient. N'invente jamais une donnée absente : ni prix, ni fournisseur, ni délai, ni quantité, ni nom de produit.
3. "questions_ouvertes" : les décisions que le document dit non prises (« pas encore décidé », « à voir », « je sais pas »), puis les informations manquantes sans lesquelles un besoin ne peut pas être paramétré (ex. seuils de réapprovisionnement, fournisseur non nommé, prix d'achat). Chaque question cite le besoin concerné ("besoin" = son numéro, ou 0 si elle est générale) et dit pourquoi elle se pose.
4. "edition" : l'édition d'Odoo si le document la mentionne ("Community" ou "Enterprise"), sinon "Non précisée".
5. Un document qui exprime peu de besoins concrets donne peu de besoins et beaucoup de questions : ne complète pas avec des besoins supposés.
6. Ne propose aucun paramétrage, aucun menu ni aucune solution : tu extrais seulement ce que dit le document.
7. "lots" : regroupe les besoins à paramétrer en 5 lots au plus, un lot par ensemble de besoins qui se paramètrent dans le même module ou le même flux (ex. produits + fournisseur + commande fournisseur automatique + traçabilité). Un besoin qui n'est qu'une décision non prise ou une donnée à fournir n'entre dans aucun lot : il reste une question ouverte. Ne mets jamais dans un même lot deux familles de produits ou deux flux dont les données diffèrent (ex. produits stockés et produits commandés à la demande, s'ils n'ont pas le même fournisseur)  : fais un lot par famille. Un lot regroupe 3 besoins au plus : au-delà, coupe-le par fonction (ex. produit et fournisseur / commande et suivi / entrepôt et livraison).
   - "besoins" : les numéros des besoins du lot (1 pour le premier besoin de la liste) ;
   - "question" : une phrase autonome qui demande comment paramétrer ces besoins dans Odoo 20.0, avec le vocabulaire métier ;
   - "contexte" : les données du document utiles au lot, recopiées telles quelles, chacune avec l'objet auquel elle se rapporte entre parenthèses.`;

const SCHEMA = {
  type: 'object',
  properties: {
    client: { type: 'string' },
    edition: { type: 'string', enum: ['Community', 'Enterprise', 'Non précisée'] },
    besoins: { type: 'array', items: { type: 'object', properties: { titre: { type: 'string' }, besoin: { type: 'string' }, contexte: { type: 'string' }, extrait: { type: 'string' } }, required: ['titre', 'besoin', 'contexte', 'extrait'], additionalProperties: false } },
    donnees_client: { type: 'array', items: { type: 'object', properties: { donnee: { type: 'string' }, valeur: { type: 'string' }, objet: { type: 'string' }, extrait: { type: 'string' } }, required: ['donnee', 'valeur', 'objet', 'extrait'], additionalProperties: false } },
    questions_ouvertes: { type: 'array', items: { type: 'object', properties: { question: { type: 'string' }, besoin: { type: 'integer' }, raison: { type: 'string' } }, required: ['question', 'besoin', 'raison'], additionalProperties: false } },
    lots: { type: 'array', items: { type: 'object', properties: { besoins: { type: 'array', items: { type: 'integer' } }, question: { type: 'string' }, contexte: { type: 'string' } }, required: ['besoins', 'question', 'contexte'], additionalProperties: false } },
  },
  required: ['client', 'edition', 'besoins', 'donnees_client', 'questions_ouvertes', 'lots'],
  additionalProperties: false,
};

const docBlock = pdf
  ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: pdf } }
  : { type: 'text', text: `Document client :\n\n${texte}` };

return {
  json: {
    source: pdf ? 'pdf' : 'texte',
    startedAt: Date.now(),
    extractBody: {
      model: 'claude-sonnet-5-5',
      max_tokens: 8000,
      output_config: { effort: 'low', format: { type: 'json_schema', schema: SCHEMA } },
      system: SYSTEM,
      messages: [{ role: 'user', content: [docBlock, { type: 'text', text: 'Extrais les besoins, les données client, les questions ouvertes et les lots de ce document.' }] }],
    },
  },
};

// Why Code: lecture de la sortie structurée, numérotation des besoins, coût et latence.
const req = $('Build extraction request').first().json;
const raw = ($json.content ?? []).find((c) => c.type === 'text')?.text ?? '';
let x;
try { x = JSON.parse(raw); } catch (e) { throw new Error(`Extraction illisible : ${raw.slice(0, 200)}`); }

const u = $json.usage ?? {};
const entree = (u.input_tokens ?? 0) + (u.cache_creation_input_tokens ?? 0) + (u.cache_read_input_tokens ?? 0);
const sortie = u.output_tokens ?? 0;
// Tarif Sonnet 5.5 par million de tokens (Anthropic au 06/10/2026) : 2 USD en entrée, 10 USD en sortie.
const usd = Math.round(((entree * 2 + sortie * 10) / 1e6) * 1e5) / 1e5;

return [{
  json: {
    source: req.source,
    client: x.client,
    edition: x.edition,
    besoins: x.besoins.map((b, i) => ({ n: i + 1, ...b })),
    donnees_client: x.donnees_client,
    questions_ouvertes: x.questions_ouvertes,
    lots: x.lots.slice(0, 5).map((l, i) => ({ n: i + 1, ...l })),
    cout: { usd, details: [{ etape: 'extraction', modele: 'claude-sonnet-5-5', entree, sortie, usd }] },
    dureeMs: Date.now() - req.startedAt,
  },
}];

// Why Code: étapes numérotées de tous les lots, prompt et schéma d'assemblage.
const ext = $('Read extraction').first().json;
const lots = $input.all().map((it, i) => ({ lot: ext.lots[i], r: it.json }));

const refs = [];
const blocks = lots.map(({ lot, r }) => {
  if (!Array.isArray(r.etapes)) return `Lot ${lot.n} (besoins ${lot.besoins.join(', ')}) : échec de la recherche (${r.error?.message ?? r.message ?? 'réponse invalide'}).`;
  const lines = r.etapes.map((e, k) => {
    const ref = `L${lot.n}.${k + 1}`;
    refs.push(ref);
    return `- ${ref} [${e.statut}] ${e.action} | menu : ${e.menu || '—'} | champ : ${e.champ || '—'} | valeur : ${e.valeur || '—'}`;
  });
  const extra = [
    ...r.avertissements.map((a) => `  Avertissement : ${a.texte}`),
    ...r.nonCouvert.map((g) => `  Non couvert : ${g}`),
  ];
  return `Lot ${lot.n} (besoins ${lot.besoins.join(', ')}) : ${lot.question}\nÉtapes :\n${lines.join('\n') || '(aucune)'}\n${extra.join('\n')}\nPages : ${[...new Set(r.sources.map((s) => s.url.split('#')[0]))].join(' ; ')}`;
}).join('\n\n');

const SYSTEM = `Tu assembles le plan de paramétrage Odoo 20.0 d'un client à partir des étapes déjà recherchées et contrôlées, lot par lot. Tu réponds en français.

Règles impératives :
1. "etapes" : toutes les étapes utiles des lots, dans l'ordre d'exécution, chacune citée par sa référence ("ref", ex. L1.3). Garde toute étape [Documenté] sauf doublon, contradiction avec le document ou réglage non demandé : n'écarte jamais une étape sur une supposition (« le réglage par défaut suffit ») qu'aucun lot ne dit. Ordonne les dépendances : installation d'une app, puis réglage qui fait apparaître un champ, puis enregistrement créé (ex. fournisseur), puis champ qui le sélectionne. Supprime les doublons (une même opération citée par deux lots : garde une seule référence). Écarte une étape qui contredit le document client ou qui ajoute un réglage que le client n'a pas demandé, en particulier : une étape qui ne fait que confirmer un comportement par défaut d'Odoo (ex. réception ou livraison en 1 étape quand un lot indique que c'est le réglage par défaut) et tout réglage multi-étapes (**Multi-Step Routes**, réception ou livraison en 2 ou 3 étapes) que le client n'exige pas ; dis-le alors dans "avertissements". Écarte aussi une étape qui place une donnée client dans un champ qui ne lui correspond pas (ex. le délai d'un fournisseur dans le délai de livraison au client), ou qui l'applique à un autre objet que celui auquel les données client la rattachent (ex. le fournisseur d'une famille de produits proposé pour une autre famille, même « si » c'est le cas).
Écarte aussi une étape contredite par un avertissement d'un autre lot sur un changement de version (ex. un lot dit que la route **Buy** est masquée par défaut depuis Odoo 19.0 : écarte l'étape qui fait activer **Buy**), et dis-le dans "avertissements".
Une action de test ou d'utilisation (confirmer une commande, valider une réception ou une livraison, ouvrir un document pour vérifier) n'est pas une étape de paramétrage : mets-la dans "tests". "ecartees" : chaque référence que tu ne retiens pas, avec sa raison courte (doublon de Lx.y, action de test, réglage non demandé, contredit…) ; toute référence ni retenue ni écartée sera remise dans le plan.
2. Tu ne modifies jamais une étape : tu choisis et ordonnes les références. L'installation des apps et la création des fournisseurs sont ajoutées par le code : ne les liste pas. "a_chercher" : les opérations de paramétrage Odoo indispensables aux besoins qu'aucune étape ne couvre (ex. un point « Non couvert » d'un lot, un réglage qui manque entre deux étapes), 5 au plus, jamais une action de test, une décision ou une donnée du client, ni ce que le comportement par défaut d'Odoo couvre déjà, ni un réglage multi-étapes non exigé ; "apres" = la référence de l'étape après laquelle l'insérer (vide pour le début). Elles seront cherchées sur le web.
3. "tests" : un test de bout en bout par flux métier du client, en étapes courtes avec les boutons et menus en anglais tels qu'ils figurent dans les étapes ou les avertissements, et "pages" = les pages des lots qui décrivent ce flux.
4. "questions" : les questions ouvertes du document, puis les points non couverts des lots qui demandent une décision ou une donnée du client. Pas de doublon.
5. "avertissements" : édition requise (Enterprise) si un lot l'indique, limites et prérequis signalés par les lots. Pas de doublon.
6. N'invente aucune donnée client : prix, délai, fournisseur, quantité restent « À renseigner » s'ils ne figurent pas dans les données client.`;

const step = { type: 'object', properties: { ref: { type: 'string' }, besoins: { type: 'array', items: { type: 'integer' } } }, required: ['ref', 'besoins'], additionalProperties: false };
const missing = { type: 'object', properties: { apres: { type: 'string' }, operation: { type: 'string' }, besoins: { type: 'array', items: { type: 'integer' } } }, required: ['apres', 'operation', 'besoins'], additionalProperties: false };
const SCHEMA = {
  type: 'object',
  properties: {
    resume: { type: 'string' },
    etapes: { type: 'array', items: step },
    a_chercher: { type: 'array', items: missing },
    ecartees: { type: 'array', items: { type: 'object', properties: { ref: { type: 'string' }, raison: { type: 'string' } }, required: ['ref', 'raison'], additionalProperties: false } },
    tests: { type: 'array', items: { type: 'object', properties: { titre: { type: 'string' }, etapes: { type: 'array', items: { type: 'string' } }, pages: { type: 'array', items: { type: 'string' } } }, required: ['titre', 'etapes', 'pages'], additionalProperties: false } },
    questions: { type: 'array', items: { type: 'object', properties: { question: { type: 'string' }, besoin: { type: 'integer' }, raison: { type: 'string' } }, required: ['question', 'besoin', 'raison'], additionalProperties: false } },
    avertissements: { type: 'array', items: { type: 'string' } },
  },
  required: ['resume', 'etapes', 'a_chercher', 'ecartees', 'tests', 'questions', 'avertissements'],
  additionalProperties: false,
};

const besoins = ext.besoins.map((b) => `${b.n}. ${b.titre} : ${b.besoin}`).join('\n');
const donnees = ext.donnees_client.map((d) => `- ${d.donnee} : ${d.valeur} (${d.objet})`).join('\n');
const questions = ext.questions_ouvertes.map((q) => `- (besoin ${q.besoin}) ${q.question} — ${q.raison}`).join('\n');
const user = `Client : ${ext.client} (édition : ${ext.edition})\n\nBesoins :\n${besoins}\n\nDonnées client :\n${donnees || '(aucune)'}\n\nQuestions ouvertes du document :\n${questions || '(aucune)'}\n\n---\n\n${blocks}`;

return [{
  json: {
    lots: lots.map(({ lot, r }) => ({ lot, r })),
    refs,
    assemblyBody: {
      model: 'claude-sonnet-5-5',
      max_tokens: 8000,
      output_config: { effort: 'low', format: { type: 'json_schema', schema: SCHEMA } },
      system: SYSTEM,
      messages: [{ role: 'user', content: user }],
    },
  },
}];

// Why Code: étapes reprises des lots avec leur statut et leur source, coût total et rendu Markdown.
const ext = $('Read extraction').first().json;
const asm = $('Build assembly request').first().json;
const res = $('Assemble plan (Claude)').first().json;
const raw = (res.content ?? []).find((c) => c.type === 'text')?.text ?? '';
let p;
try { p = JSON.parse(raw); } catch (e) { throw new Error(`Assemblage illisible : ${raw.slice(0, 200)}`); }

// Étape d'origine par référence : statut, source et champs ne viennent jamais de l'assemblage.
const byRef = new Map();
for (const { lot, r } of asm.lots) (r.etapes ?? []).forEach((e, k) => byRef.set(`L${lot.n}.${k + 1}`, { lot: lot.n, e }));
const seen = new Set();
const etapes = [];
for (const s of p.etapes) {
  const o = byRef.get(s.ref);
  if (o && seen.has(s.ref)) continue;
  if (o) {
    seen.add(s.ref);
    etapes.push({ n: etapes.length + 1, ref: s.ref, besoins: s.besoins, action: o.e.action, menu: o.e.menu, champ: o.e.champ, valeur: o.e.valeur, detail: o.e.texte, statut: o.e.statut, source: o.e.source, ...(o.e.raison ? { raison: o.e.raison } : {}) });
  }
}

// Étape « Documenté » d'un lot ni retenue ni écartée (avec raison) par l'assemblage : remise après l'étape qui la précède dans son lot.
const ecartees = new Map((p.ecartees ?? []).map((x) => [x.ref, x.raison]));
for (const { lot, r } of asm.lots) {
  (r.etapes ?? []).forEach((e, k) => {
    const ref = `L${lot.n}.${k + 1}`;
    if (seen.has(ref) || ecartees.has(ref) || e.statut !== 'Documenté') return;
    let at = -1;
    for (let j = k; j >= 1 && at < 0; j--) at = etapes.findIndex((x) => x.ref === `L${lot.n}.${j}`);
    etapes.splice(at + 1, 0, { n: 0, ref, besoins: [], action: e.action, menu: e.menu, champ: e.champ, valeur: e.valeur, detail: e.texte, statut: e.statut, source: e.source, remise: true });
    seen.add(ref);
  });
}

// Opérations manquantes : étape 🌐 Web si le web l'a trouvée et que le contrôle la garde, sinon « À vérifier ».
const webRes = $('Search web (plan)').isExecuted ? $('Search web (plan)').first().json : null;
const wcheck = $('Check web steps (Claude)').isExecuted ? $('Check web steps (Claude)').first().json : null;
const cands = $('Build web check (plan)').isExecuted ? $('Build web check (plan)').first().json.candidates : [];
let verdicts = new Map();
try { verdicts = new Map(JSON.parse((wcheck?.content ?? []).find((c) => c.type === 'text')?.text ?? '{"verdicts":[]}').verdicts.map((v) => [v.id, v])); } catch (e) { /* contrôle illisible : aucune étape web gardée */ }
const rejetsWeb = [];
$('Build web request (plan)').first().json.points.forEach((pt, k) => {
  const c = cands.find((x) => x.point === k);
  const v = c && verdicts.get(c.id);
  let step;
  if (c && v?.garder) {
    const { id, point, apres, operation, ...s } = c;
    step = { n: 0, ref: 'web', ...s, statut: 'Web' };
  } else {
    if (c) rejetsWeb.push({ operation: pt.operation, action: c.action, source: c.source, raison: v?.raison ?? 'Non contrôlée.' });
    step = { n: 0, ref: '', besoins: pt.besoins, action: pt.operation, menu: '', champ: '', valeur: '', detail: '', statut: 'À vérifier', source: [],
      raison: c ? `Trouvée sur le web mais rejetée au contrôle : ${v?.raison ?? 'non contrôlée'}.` : (webRes ? 'Non trouvée dans la documentation ni sur le web.' : 'Non trouvée dans la documentation.') };
  }
  const at = pt.apres ? etapes.findIndex((e) => e.ref === pt.apres) : -1;
  etapes.splice(at + 1, 0, step);
});

// Prérequis ajoutés par le code (« À vérifier ») : installation des apps citées dans les menus,
// puis création de chaque fournisseur du document avant le premier champ Vendor qui le nomme.
const APPS = [['Sales', /\bSales\b|\bdevis\b|\bquotation\b/i], ['Purchase', /\bPurchase app\b|onglet \*?\*?Purchase|\bVendor\b/], ['Inventory', /\bInventory app\b/],
  ['Invoicing', /\bInvoicing app\b/], ['Helpdesk', /\bHelpdesk( app)?\s*‣/], ['Planning', /\bPlanning( app)?\s*‣/],
  ['Subscriptions', /\bSubscriptions( app)?\s*‣/], ['Project', /\bProject( app)?\s*‣/], ['Timesheets', /\bTimesheets( app)?\s*‣/]];
const stepText = (e) => [e.action, e.menu, e.champ, e.valeur, e.detail].join(' ');
const added = (e) => !e.ref;
const cited = [...etapes.map(stepText), ...p.tests.flatMap((t) => t.etapes)];
const apps = APPS.filter(([, re]) => cited.some((s) => re.test(s))).map(([a]) => a);
for (let i = etapes.length - 1; i >= 0; i--) if (added(etapes[i]) && /install/i.test(etapes[i].action)) etapes.splice(i, 1);
if (apps.length) etapes.unshift({ n: 0, ref: '', besoins: [], action: `Installer les apps ${apps.join(', ')}`, menu: 'Apps', champ: '', valeur: apps.join(', '), detail: '', statut: 'À vérifier', source: [], raison: 'Ajoutée par le code : apps citées dans les menus du plan.' });
const vendors = [...new Set(ext.donnees_client.filter((d) => /fournisseur|vendor/i.test(`${d.donnee} ${d.objet ?? ''}`)).map((d) => d.valeur.trim()))]
  .filter((v) => v && !/renseigner|liste|plusieurs/i.test(v));
for (const v of vendors) {
  const use = etapes.findIndex((e) => /Vendor|fournisseur/i.test(`${e.champ} ${e.valeur} ${e.action}`) && !/cr[ée]er|create/i.test(e.action) && e.valeur.includes(v));
  if (use < 0) continue;
  const isCreate = (e) => /cr[ée]er|create/i.test(e.action) && stepText(e).includes(v);
  const at = etapes.findIndex(isCreate);
  if (at >= 0 && at < use) continue;
  const create = at >= 0 ? etapes.splice(at, 1)[0]
    : { n: 0, ref: '', besoins: etapes[use].besoins, action: `Créer le fournisseur ${v}`, menu: 'Purchase app ‣ Orders ‣ Vendors', champ: 'Name', valeur: v, detail: '', statut: 'À vérifier', source: [], raison: 'Ajoutée par le code : fournisseur à créer avant de le sélectionner.' };
  etapes.splice(etapes.findIndex((e) => /Vendor|fournisseur/i.test(`${e.champ} ${e.valeur} ${e.action}`) && !/cr[ée]er|create/i.test(e.action) && e.valeur.includes(v)), 0, create);
}
etapes.forEach((e, i) => { e.n = i + 1; });

// Coût : extraction + chaque lot (odoo-question) + assemblage (Sonnet 5.5 : 2 / 10 USD par million de tokens).
const u = res.usage ?? {};
const entree = (u.input_tokens ?? 0) + (u.cache_creation_input_tokens ?? 0) + (u.cache_read_input_tokens ?? 0);
const sortie = u.output_tokens ?? 0;
const details = [
  ...ext.cout.details,
  ...asm.lots.map(({ lot, r }) => ({ etape: `lot ${lot.n}`, modele: r.modele ?? null, usd: r.cout?.usd ?? null, dureeMs: r.dureeMs ?? null })),
  { etape: 'assemblage', modele: 'claude-sonnet-5-5', entree, sortie, usd: Math.round(((entree * 2 + sortie * 10) / 1e6) * 1e5) / 1e5 },
];
if (wcheck?.usage) {
  const cu = wcheck.usage;
  const ce = (cu.input_tokens ?? 0) + (cu.cache_creation_input_tokens ?? 0) + (cu.cache_read_input_tokens ?? 0);
  details.push({ etape: 'contrôle web', modele: 'claude-haiku-5-5', entree: ce, sortie: cu.output_tokens ?? 0, usd: Math.round(((ce * 0.1 + (cu.output_tokens ?? 0) * 0.5) / 1e6) * 1e5) / 1e5 });
}
if (webRes) {
  const wu = webRes.usage ?? {};
  const we = (wu.input_tokens ?? 0) + (wu.cache_creation_input_tokens ?? 0) + (wu.cache_read_input_tokens ?? 0);
  const recherches = wu.server_tool_use?.web_search_requests ?? 0;
  // Haiku 5.5 : 0,10 / 0,50 USD par million de tokens ; recherche web : 10 USD les 1 000.
  details.push({ etape: 'web', modele: 'claude-haiku-5-5', entree: we, sortie: wu.output_tokens ?? 0, recherches, usd: Math.round(((we * 0.1 + (wu.output_tokens ?? 0) * 0.5) / 1e6 + recherches * 0.01) * 1e5) / 1e5 });
}
const usd = details.some((d) => d.usd === null) ? null : Math.round(details.reduce((t, d) => t + d.usd, 0) * 1e5) / 1e5;
const dureeMs = Date.now() - $('Build extraction request').first().json.startedAt;

const parStatut = {};
for (const e of etapes) parStatut[e.statut] = (parStatut[e.statut] ?? 0) + 1;

const md = [
  `# Plan Odoo 20 — ${ext.client}`,
  '',
  `Édition : ${ext.edition}. ${p.resume}`,
  '',
  `Étapes : ${Object.entries(parStatut).map(([k, v]) => `${v} ${k}`).join(', ')}.`,
  '',
  '## Besoins compris',
  ...ext.besoins.map((b) => `${b.n}. **${b.titre}** : ${b.besoin}`),
  '',
  '## Étapes',
