// Why Code: lecture des étapes web (repères [Pn], citations des résultats) et prompt de contrôle par Haiku.
const wb = $('Build web request (plan)').first().json;
const ext = $('Read extraction').first().json;
const araw = ($('Assemble plan (Claude)').first().json.content ?? []).find((c) => c.type === 'text')?.text ?? '{}';
const asm = JSON.parse(araw);
const content = Array.isArray($json.content) ? $json.content : [];
const resultUrls = new Set(content.filter((c) => c.type === 'web_search_tool_result' && Array.isArray(c.content)).flatMap((c) => c.content.map((x) => x.url)));
const seg = {};
let cur = null;
for (const c of content.filter((x) => x.type === 'text')) {
  for (const part of c.text.split(/(\[P\d+\])/)) {
    const m = part.match(/^\[P(\d+)\]$/);
    if (m) { cur = Number(m[1]); seg[cur] ??= { text: '', cites: [] }; } else if (cur) seg[cur].text += part;
  }
  if (cur) seg[cur].cites.push(...(c.citations ?? []).filter((x) => x.type === 'web_search_result_location' && resultUrls.has(x.url)));
}
const otherVersion = (u) => (u.match(/odoo\.com\/documentation\/((?!20\.0)[^/]+)\//) ?? [])[1];
const candidates = [];
wb.points.forEach((pt, k) => {
  const s = seg[k + 1];
  const text = (s?.text ?? '').replace(/\*\*/g, '').trim();
  const line = text.match(/Action\s*:\s*(.*?)\s*\|\s*Menu\s*:\s*(.*?)\s*\|\s*Champ\s*:\s*(.*?)\s*\|\s*Valeur\s*:\s*([^\n]*)/);
  const urls = [...new Set((s?.cites ?? []).map((x) => x.url))];
  if (!line || !urls.length || /^Non trouvé/i.test(text)) return;
  const versions = [...new Set(urls.map(otherVersion).filter(Boolean))];
  candidates.push({ id: `W${k + 1}`, point: k, apres: pt.apres, besoins: pt.besoins, operation: pt.operation, action: line[1], menu: line[2], champ: line[3], valeur: line[4].trim(),
    detail: text.replace(line[0], '').trim(), source: urls, extraits: [...new Set(s.cites.map((x) => x.cited_text))].slice(0, 4),
    ...(versions.length ? { raison: `Page web d'une autre version d'Odoo (${versions.join(', ')}).` } : {}) });
});

const SYSTEM = `Tu contrôles des étapes de paramétrage Odoo 20.0 trouvées sur le web avant de les ajouter à un plan client.
Pour chaque étape, "garder" vaut true seulement si les quatre conditions sont vraies :
1. Les extraits cités disent l'action, le menu, le champ et la valeur de l'étape (une valeur « À renseigner » ou une donnée client n'a pas à y figurer).
2. L'étape ne contredit aucun fait établi par la documentation (ex. une route masquée par défaut depuis Odoo 19.0 : une étape qui la fait activer est rejetée).
3. L'étape fait seulement l'opération demandée, sans réglage voisin ni ajout que le besoin n'exige pas.
4. Une donnée client n'y est appliquée qu'à l'objet auquel les données client la rattachent.
Donne une raison courte en français.`;
const list = candidates.map((c) => `- id "${c.id}" — opération demandée : ${c.operation}\n  étape : ${c.action} | menu : ${c.menu} | champ : ${c.champ} | valeur : ${c.valeur}\n  extraits cités : ${c.extraits.map((e) => `« ${e} »`).join(' ; ')}`).join('\n');
const user = `Données client : ${ext.donnees_client.map((d) => `${d.donnee} : ${d.valeur} (${d.objet})`).join(' ; ')}\n\nFaits établis par la documentation :\n${(asm.avertissements ?? []).map((a) => `- ${a}`).join('\n') || '(aucun)'}\n\nÉtapes à contrôler :\n${list || '(aucune)'}`;
const SCHEMA = { type: 'object', properties: { verdicts: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, garder: { type: 'boolean' }, raison: { type: 'string' } }, required: ['id', 'garder', 'raison'], additionalProperties: false } } }, required: ['verdicts'], additionalProperties: false };
return [{ json: { candidates, checkBody: { model: 'claude-haiku-5-5', max_tokens: 4000, output_config: { effort: 'low', format: { type: 'json_schema', schema: SCHEMA } }, system: SYSTEM, messages: [{ role: 'user', content: user }] } } }];
